package org.sigf.repositories;
import java.sql.*;import java.time.LocalDate;import java.util.*;import org.sigf.config.Database;import org.sigf.domain.ReportGrid;
public final class ReportRepository {
 private final Database db; public ReportRepository(Database db){this.db=db;}
 private static final Map<String,String> QUERIES=Map.ofEntries(
  Map.entry("suppliers","select id,name,coalesce(phone,''),active from supplier order by id"),
  Map.entry("customers","select id,name,coalesce(phone,''),ruc from customer order by id"),
  Map.entry("users","select id,username,role,active from app_user order by id"),
  Map.entry("batches","select b.id,p.code,p.name,b.lot,b.expires_on,b.quantity,b.blocked from batch b join product p on p.id=b.product_id order by b.expires_on,b.id"),
  Map.entry("sales","select s.id,s.created_at,coalesce(c.name,''),s.subtotal,s.tax,s.total,s.status from sale s left join customer c on c.id=s.customer_id order by s.id desc"),
  Map.entry("purchases","select p.id,p.created_at,coalesce(s.name,''),p.total from purchase p left join supplier s on s.id=p.supplier_id order by p.id desc"),
  Map.entry("movements","select m.id,m.created_at,p.name,b.lot,m.kind,m.quantity,u.username from stock_movement m join batch b on b.id=m.batch_id join product p on p.id=b.product_id join app_user u on u.id=m.actor_id order by m.id desc"),
  Map.entry("settings","select key,value from setting where key not in ('tax_rate','pharmacy_name','business_details') order by key"),
  Map.entry("audit","select a.id,a.created_at,coalesce(u.username,''),a.action,coalesce(a.details,'') from audit_log a left join app_user u on u.id=a.actor_id order by a.id desc"),
  Map.entry("stock","select p.id,p.code,p.name,p.sale_price,p.minimum_stock,coalesce(sum(b.quantity),0) as total,coalesce(sum(b.quantity) filter(where not b.blocked and b.expires_on>=current_date),0) as vendible,p.tax_rate,p.active from product p left join batch b on b.product_id=p.id group by p.id order by p.name"),
  Map.entry("top","select p.code,p.name,sum(l.quantity) as unidades,sum(l.quantity*l.unit_price) as importe from sale_line l join sale s on s.id=l.sale_id join product p on p.id=l.product_id where s.status='CONFIRMED' group by p.id order by unidades desc"),
  Map.entry("dashboard_low","select p.code as codigo,p.name as producto,p.minimum_stock as minimo,coalesce(sum(b.quantity) filter(where not b.blocked and b.expires_on>=current_date),0) as vendible from product p left join batch b on b.product_id=p.id where p.active group by p.id having coalesce(sum(b.quantity) filter(where not b.blocked and b.expires_on>=current_date),0)<=p.minimum_stock order by p.name"),
  Map.entry("dashboard_expiring","select p.name as producto,b.lot as lote,b.expires_on as vence,b.quantity as cantidad from batch b join product p on p.id=b.product_id where b.quantity>0 and b.expires_on<=current_date+coalesce((select value::integer from setting where key='expiry_days'),30) order by b.expires_on,b.id limit 100"),
  Map.entry("dashboard_recent","select m.created_at as fecha,p.name as producto,m.kind as tipo,m.quantity as cantidad from stock_movement m join batch b on b.id=m.batch_id join product p on p.id=b.product_id order by m.id desc limit 20"),
  Map.entry("dashboard","select (select count(*) from product where active) as productos,(select coalesce(sum(quantity),0) from batch where not blocked and expires_on>=current_date) as unidades_vendibles,(select count(*) from batch where quantity>0 and expires_on between current_date and current_date+coalesce((select value::integer from setting where key='expiry_days'),30)) as lotes_por_vencer,(select count(*) from product p where p.active and (select coalesce(sum(b.quantity),0) from batch b where b.product_id=p.id and not b.blocked and b.expires_on>=current_date)<=p.minimum_stock) as productos_bajos,(select coalesce(sum(total),0) from sale where status='CONFIRMED' and created_at::date=current_date) as ventas_hoy")
 );
 public ReportGrid grid(String name) throws SQLException {String sql=QUERIES.get(name);if(sql==null)throw new IllegalArgumentException("Consulta desconocida");try(Connection c=db.connection();PreparedStatement q=c.prepareStatement(sql);ResultSet r=q.executeQuery()){return grid(r);}}
 public ReportGrid report(String name,LocalDate from,LocalDate to)throws SQLException {if(from==null||to==null||to.isBefore(from))throw new IllegalArgumentException("Período inválido");if(name.equals("tax_summary")){try(Connection c=db.connection();PreparedStatement q=c.prepareStatement("select exists(select 1 from sale_line l join sale s on s.id=l.sale_id where s.status='CONFIRMED' and s.created_at::date between ? and ? and l.tax_rate is null)")){q.setDate(1,java.sql.Date.valueOf(from));q.setDate(2,java.sql.Date.valueOf(to));try(ResultSet r=q.executeQuery()){r.next();if(r.getBoolean(1))throw new IllegalArgumentException("Hay ventas históricas sin detalle de IVA; el resumen sería incompleto");}}}String sql=switch(name){case "voided_docs"->"select s.id,coalesce(d.series,'SIN SERIE') as serie,d.number as numero,s.created_at,s.voided_at,s.void_reason,s.total from sale s left join internal_document d on d.sale_id=s.id where s.status='VOID' and s.voided_at::date between ? and ? order by s.voided_at";case "tax_summary"->"select tax_rate as tasa_iva,sum(base) as base,sum(round(base*tax_rate,2)) as iva from (select s.id,l.product_id,l.tax_rate,sum(l.unit_price*l.quantity) as base from sale_line l join sale s on s.id=l.sale_id where s.status='CONFIRMED' and s.created_at::date between ? and ? and l.tax_rate is not null group by s.id,l.product_id,l.tax_rate) x group by tax_rate order by tax_rate";case "internal_docs"->"select s.id,coalesce(d.series,'SIN SERIE') as serie,d.number as numero,s.created_at,coalesce(h.customer_name,'SIN DATOS HISTORICOS') as cliente,s.subtotal,s.tax,s.total,s.status,s.voided_at,s.void_reason from sale s left join internal_document d on d.sale_id=s.id left join sale_receipt_snapshot h on h.sale_id=s.id where s.created_at::date between ? and ? order by s.id";case "sales"->"select id,created_at,subtotal,tax,total,status from sale where created_at::date between ? and ? order by id desc";case "purchases"->"select id,created_at,supplier_id,total from purchase where created_at::date between ? and ? order by id desc";case "movements"->"select id,created_at,batch_id,kind,quantity,actor_id from stock_movement where created_at::date between ? and ? order by id desc";case "audit"->"select id,created_at,actor_id,action,details from audit_log where created_at::date between ? and ? order by id desc";case "batches"->"select b.id,p.name,b.lot,b.expires_on,b.quantity,b.blocked from batch b join product p on p.id=b.product_id where b.expires_on between ? and ? order by b.expires_on";case "top"->"select p.code,p.name,sum(l.quantity) as unidades,sum(l.quantity*l.unit_price) as importe from sale_line l join sale s on s.id=l.sale_id join product p on p.id=l.product_id where s.status='CONFIRMED' and s.created_at::date between ? and ? group by p.id order by unidades desc";default->null;};if(sql==null)return grid(name);try(Connection c=db.connection();PreparedStatement s=c.prepareStatement(sql)){s.setDate(1,java.sql.Date.valueOf(from));s.setDate(2,java.sql.Date.valueOf(to));try(ResultSet r=s.executeQuery()){return grid(r);}}}
 private static ReportGrid grid(ResultSet r)throws SQLException{var md=r.getMetaData();List<String> cols=new ArrayList<>();for(int i=1;i<=md.getColumnCount();i++)cols.add(md.getColumnLabel(i));List<List<String>> rows=new ArrayList<>();while(r.next()){List<String> row=new ArrayList<>();for(int i=1;i<=cols.size();i++)row.add(Objects.toString(r.getObject(i),""));rows.add(row);}return new ReportGrid(cols,rows);}
}
